class Solution {
public:
    int minOperations(vector<int>& nums, vector<int>& locked, int k) {
        int n = nums.size();
        // Fenwick Tree for inversion count
        vector<int> bit(n + 2, 0);
        auto add = [&](int idx, int val) {
            for (; idx <= n; idx += idx & -idx) bit[idx] += val;
        };
        auto sum = [&](int idx) {
            int s = 0;
            for (; idx > 0; idx -= idx & -idx) s += bit[idx];
            return s;
        };
        long long inv = 0;
        int prefMax = 0;
        int needUnlock = 0;
        for (int i = 0; i < n; ++i) {
            // count previous elements greater than nums[i]
            int lessOrEq = sum(nums[i]);          // number of previous <= nums[i]
            inv += (long long)i - lessOrEq;       // previous count is i
            add(nums[i], 1);
            prefMax = max(prefMax, nums[i]);
            if (locked[i] == 1) {
                if (!(prefMax == i + 1 && nums[i] == i + 1))
                    ++needUnlock;
            }
        }
        if (needUnlock > k) return -1;
        long long ans = inv + needUnlock;
        return (int)ans;
    }
};
